 need(base?.schemaVersion===1&&Array.isArray(base.events)&&Array.isArray(base.sources)&&Number.isFinite(now));
 need(supplement?.contract==='encore.fixed-legacy-supplement'&&supplement.version===1&&supplement.autoUpdated===false&&supplement.timezone==='Asia/Taipei'&&stamp(supplement.observedFrom)&&stamp(supplement.observedThrough)&&supplement.observedFrom<=supplement.observedThrough&&Array.isArray(supplement.events)&&supplement.events.length<=100);
 const articleIds=new Set(),ids=new Set(),kinds=new Set(['general','member','card','fan','presale','additional','registration','package','announced','changed','cancelled']);
 for(const e of supplement.events){need(text(e.id,100)&&!ids.has(e.id)&&text(e.title,300)&&text(e.venue,160)&&['music','theatre','baseball','other'].includes(e.category)&&e.sourceId==='legacy'&&safe(e.sourceUrl)&&!articleIds.has(e.sourceUrl)&&stamp(e.fetchedAt)&&e.fetchedAt>=supplement.observedFrom&&e.fetchedAt<=supplement.observedThrough&&(!e.eventAt||stamp(e.eventAt))&&(!e.doorsAt||stamp(e.doorsAt))&&text(e.eventDateText??'',200)&&Array.isArray(e.sourceRecords)&&e.sourceRecords.length===1&&e.sourceRecords[0].url===e.sourceUrl&&e.sourceRecords[0].sourceId==='legacy'&&e.sourceRecords[0].fetchedAt===e.fetchedAt&&Array.isArray(e.sale_phases)&&e.sale_phases.length>0&&e.sale_phases.length<=20);ids.add(e.id);articleIds.add(e.sourceUrl);const phases=new Set();for(const p of e.sale_phases){need(text(p.id,100)&&!phases.has(p.id)&&kinds.has(p.kind)&&text(p.label,160)&&text(p.eligibility,500)&&text(p.evidenceText,500)&&p.sourceUrl===e.sourceUrl&&stamp(p.fetchedAt)&&p.fetchedAt>=supplement.observedFrom&&p.fetchedAt<=supplement.observedThrough&&(p.startsAt===null||stamp(p.startsAt))&&(p.endsAt===null||stamp(p.endsAt))&&(!p.endsAt||!p.startsAt||p.endsAt>p.startsAt)&&Array.isArray(p.appliesToSessions)&&p.appliesToSessions.every(stamp));phases.add(p.id);}}
